<script setup>import {ref} from 'vue';const polls=ref([{q:'What matters most when choosing a news subscription?',opts:[['Trust and accuracy',42],['Ad-free reading',26],['Local coverage',19],['Exclusive analysis',13]]},{q:'How do you prefer to catch up on breaking news?',opts:[['Short summaries',39],['Full articles',31],['Video shorts',18],['Live blog',12]]}]);</script><template><div class="page narrow"><div class="page-heading"><span>COMMUNITY</span><h1>Pulse Polls</h1><p>Vote on the questions shaping the conversation. Results update live.</p></div><div class="poll-big" v-for="(p,i) in polls"><span class="eyebrow">LIVE POLL · {{(18+i*7)+',000'}} votes</span><h2>{{p.q}}</h2><button v-for="o in p.opts"><span>{{o[0]}}</span><b>{{o[1]}}%</b><i :style="{width:o[1]+'%'}"></i></button><small>One vote per account · Results are not scientific surveys.</small></div></div></template>